<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue';import {campaignApi} from '../campaign-api';import type {WorkTab} from '../stores';import Modal from './Modal.vue';import CampaignStaffSearch from './CampaignStaffSearch.vue';
const props=defineProps<{campaign:any;store:any;stores:any[];permissions:any;tab:WorkTab;initial?:string}>();
const active=ref(props.initial||'details'),loading=ref(true),errors=ref<Record<string,string>>({}),message=ref(''),data=ref<any>({}),form=ref<any>({}),own=ref<any[]>([]),counts=ref<any>({extra_support_count:0,supervisor_count:0,notes:''}),checks=ref<Record<string,any>>({}),baseline=ref<any>({}),version=ref(''),ownRequest=ref(crypto.randomUUID());
const requestForm=ref<any>(null),requestBaseline=ref(''),removing=ref<any>(null),assigned=ref<any>(null),assignedRows=ref<any[]>([]),assignedBaseline=ref(''),assignedVersion=ref(''),assignedRequest=ref(''),confirmDiscard=ref(''),reloadOwn=ref(false),fieldTarget=ref('supervisor');
const promo=[['outdoor_vendor','外場廠商'],['red_bean_cake','紅豆餅／雞蛋糕'],['circulation','循環'],['quantum','量子'],['bone_density','骨密'],['supervisor','督導'],['manager','經理'],['tasting','試飲'],['activity_team','活動組'],...Array.from({length:6},(_,i)=>['sales'+(i+1),'業務 '+(i+1)]),['indoor_pt1','內場工讀 1（09–13）'],['indoor_pt2','內場工讀 2（09–13）']];
const inventory=[['has_external_inventory_company','是否有外盤公司'],['planned_inventory_time','預計盤點時間'],['inventory_staff','盤點組人員']];
const fields=computed(()=>props.campaign.campaign_type==='inventory'?inventory:promo);
const changed=(key:string,v:any)=>!!baseline.value[key]&&JSON.stringify(v)!==baseline.value[key];
const dirty=computed(()=>changed('details',form.value)||changed('own',own.value)||changed('counts',counts.value)||changed('checks',checks.value)||!!requestForm.value&&JSON.stringify(requestForm.value)!==requestBaseline.value||!!assigned.value&&JSON.stringify(assignedRows.value)!==assignedBaseline.value);
watch(dirty,v=>props.tab.dirty=v,{flush:'sync'});watch(own,()=>ownRequest.value=crypto.randomUUID(),{deep:true,flush:'sync'});watch(assignedRows,()=>assignedRequest.value=crypto.randomUUID(),{deep:true,flush:'sync'});props.tab.submitOnly=true;
const completed=computed(()=>data.value.checklist?.filter((i:any)=>checks.value[i.id]?.is_completed).length||0),hideCompleted=ref(false);
const visibleChecks=computed(()=>(errors.value.completions||errors.value.checklist?[]:data.value.checklist||[]).filter((i:any)=>!hideCompleted.value||!checks.value[i.id]?.is_completed));
function snapshot(key:string,value:any){baseline.value[key]=JSON.stringify(value);}
async function load(){loading.value=true;errors.value={};const names=['details','ownStaff','requests','supportStaff','headcount','checklist','completions'];const results=await Promise.allSettled(names.map(k=>campaignApi(k,{campaign_id:props.campaign.id,store_id:props.store.id,requesting_store_id:props.store.id})));results.forEach((r,i)=>{const k=names[i];if(r.status==='fulfilled'){data.value[k]=r.value.data||[];if(k==='ownStaff')version.value=r.value.version;}else errors.value[k]=(r.reason as Error).message;});
 if(!errors.value.details){const r=data.value.details[0]||{};form.value=Object.fromEntries([...promo,...inventory,['notes','備註']].map(([k])=>[k,r[k]||'']));snapshot('details',form.value);}
 if(!errors.value.ownStaff){own.value=data.value.ownStaff.map((r:any)=>({...r}));snapshot('own',own.value);}
 if(!errors.value.headcount){const r=data.value.headcount[0]||{};counts.value={extra_support_count:r.extra_support_count||0,supervisor_count:r.supervisor_count||0,notes:r.notes||''};snapshot('counts',counts.value);}
 if(!errors.value.completions&&!errors.value.checklist){checks.value=Object.fromEntries(data.value.checklist.map((i:any)=>{const r=data.value.completions.find((c:any)=>c.checklist_item_id===i.id)||{};return [i.id,{is_completed:!!r.is_completed,manager_note:r.manager_note||'',store_assigned_person:r.store_assigned_person||''}];}));snapshot('checks',checks.value);}
 loading.value=false;
}
async function run(key:string,task:()=>Promise<void>){if(props.tab.busy)return;props.tab.busy=true;delete errors.value.action;message.value='';try{await task();message.value=key+'已儲存';}catch(e){errors.value.action=(e as Error).message;}finally{props.tab.busy=false;}}
function saveDetails(){void run('門市配置',async()=>{await campaignApi('details',{},'POST',{...form.value,campaign_id:props.campaign.id,store_id:props.store.id});snapshot('details',form.value);});}
function addStaff(r:any){if(!own.value.some(x=>x.employee_code===r.employee_code))own.value.push({employee_code:r.employee_code,employee_name:r.employee_name,position:r.position||r.current_position||'',is_manually_added:true});}
function saveOwn(){void run('本店人員',async()=>{const r=await campaignApi('ownStaff',{},'PUT',{campaign_id:props.campaign.id,scope:props.store.id,rows:own.value,version:version.value,requestId:ownRequest.value});version.value=r.version;snapshot('own',own.value);});}
async function fromMonthly(){reloadOwn.value=false;await run('月資料載入草稿，請再儲存本店人員',async()=>{const r=await campaignApi('employees',{store_id:props.store.id});own.value=(r.data||[]).map((e:any)=>({employee_code:e.employee_code,employee_name:e.employee_name,position:e.position||'',is_manually_added:false}));message.value='已載入 '+r.year_month;});if(!errors.value.action)message.value='已載入月度人員至草稿，請按「儲存本店人員」才會生效。';}
function saveCount(){void run('預估人數',async()=>{await campaignApi('headcount',{},'POST',{...counts.value,campaign_id:props.campaign.id,store_id:props.store.id});snapshot('counts',counts.value);});}
function editRequest(r?:any){requestForm.value={existing:!!r,supporting_store_id:r?.supporting_store_id||'',requested_count:r?.requested_count||1,notes:r?.notes||''};requestBaseline.value=JSON.stringify(requestForm.value);}
async function refreshRequests(){data.value.requests=(await campaignApi('requests',{campaign_id:props.campaign.id,requesting_store_id:props.store.id})).data;data.value.supportStaff=(await campaignApi('supportStaff',{campaign_id:props.campaign.id})).data;}
function saveRequest(){void run('支援需求',async()=>{await campaignApi('requests',{},'POST',{...requestForm.value,campaign_id:props.campaign.id,requesting_store_id:props.store.id});requestForm.value=null;await refreshRequests();});}
function deleteRequest(){void run('支援需求刪除',async()=>{await campaignApi('requests',{},'DELETE',{id:removing.value.id});removing.value=null;await refreshRequests();});}
async function openAssigned(r:any){await run('支援人員讀取',async()=>{const result=await campaignApi('supportStaff',{campaign_id:props.campaign.id,support_request_id:r.id});assignedRows.value=result.data;assignedVersion.value=result.version;assignedBaseline.value=JSON.stringify(assignedRows.value);assigned.value=r;});if(!errors.value.action)message.value='';}
function addAssigned(r:any){if(!assignedRows.value.some(x=>x.employee_code===r.employee_code))assignedRows.value.push({employee_code:r.employee_code,employee_name:r.employee_name,position:r.position||r.current_position||''});}
function saveAssigned(){void run('支援指派',async()=>{await campaignApi('supportStaff',{},'PUT',{campaign_id:props.campaign.id,scope:assigned.value.id,rows:assignedRows.value,version:assignedVersion.value,requestId:assignedRequest.value});assigned.value=null;await refreshRequests();});}
function closeInner(kind:string){if(props.tab.busy)return;const changed=kind==='request'?JSON.stringify(requestForm.value)!==requestBaseline.value:JSON.stringify(assignedRows.value)!==assignedBaseline.value;if(changed)confirmDiscard.value=kind;else if(kind==='request')requestForm.value=null;else assigned.value=null;}
function saveCheck(id:string){void run('工作回報',async()=>{await campaignApi('completions',{},'POST',{...checks.value[id],checklist_item_id:id,store_id:props.store.id});const old=JSON.parse(baseline.value.checks);old[id]={...checks.value[id]};snapshot('checks',old);});}
function discardChanges(){const k=confirmDiscard.value;if(k==='request')requestForm.value=null;else if(k==='assigned')assigned.value=null;else if(k==='details')form.value=JSON.parse(baseline.value.details);else if(k==='own')own.value=JSON.parse(baseline.value.own);else if(k==='counts')counts.value=JSON.parse(baseline.value.counts);else if(k==='checks')checks.value=JSON.parse(baseline.value.checks);confirmDiscard.value='';}
onMounted(load);
</script>
<template><nav class="sections" aria-label="門市規劃分區"><button v-for="[key,label] in [['details','門市配置'],['people','本店與支援人力'],['checklist','工作完成回報']]" :aria-pressed="active===key" :disabled="tab.busy" @click="active=key">{{label}}</button></nav><p v-if="loading">正在讀取門市規劃…</p><template v-else>
<div v-for="(value,key) in errors" :key="key" role="alert" class="notice error">{{value}}</div><p v-if="message" role="status" class="notice">{{message}}</p>
<section v-show="active==='details'"><form @submit.prevent="saveDetails"><fieldset :disabled="!permissions.details||tab.busy||!!errors.details"><div class="fields"><label v-for="[key,label] in fields">{{label}}<input v-model="form[key]"></label><label class="wide">備註<textarea v-model="form.notes" rows="3"/></label></div><details><summary>搜尋人員帶入欄位</summary><label>填入欄位<select v-model="fieldTarget"><option v-for="[key,label] in fields" :value="key">{{label}}</option></select></label><CampaignStaffSearch @select="r=>form[fieldTarget]=[form[fieldTarget],r.employee_name].filter(Boolean).join('、')"/></details><div class="dialog-actions"><button type="button" v-if="permissions.details&&changed('details',form)" @click="confirmDiscard='details'">取消配置修改</button><button v-if="permissions.details" class="primary" :disabled="!changed('details',form)">儲存門市配置</button></div></fieldset></form></section>
<section v-show="active==='people'"><h3>本店活動人員（{{own.length}} 人）</h3><template v-if="!errors.ownStaff"><div v-if="permissions.ownStaff"><CampaignStaffSearch :disabled="tab.busy" @select="addStaff"/><button :disabled="tab.busy" @click="reloadOwn=true">從月度人員重新載入</button></div><div class="module-table"><table><thead><tr><th>員編</th><th>姓名</th><th>職位</th><th>操作</th></tr></thead><tbody><tr v-for="(r,i) in own" :key="r.employee_code"><td>{{r.employee_code}}</td><td>{{r.employee_name}}</td><td>{{r.position}}</td><td><button v-if="permissions.ownStaff" :disabled="tab.busy" @click="own.splice(i,1)">移除</button></td></tr></tbody></table></div><p v-if="!own.length">尚未安排本店人員。</p><button v-if="permissions.ownStaff&&changed('own',own)" :disabled="tab.busy" @click="confirmDiscard='own'">取消人員修改</button><button v-if="permissions.ownStaff" class="primary" :disabled="tab.busy||!changed('own',own)" @click="saveOwn">儲存本店人員</button></template>
<h3>支援需求與指派</h3><button v-if="permissions.requests" :disabled="tab.busy||!!errors.requests" @click="editRequest()">新增支援需求</button><div class="module-table"><table><thead><tr><th>支援門市</th><th>需求人數</th><th>已指派人員</th><th>備註</th><th>操作</th></tr></thead><tbody><tr v-for="r in data.requests" :key="r.id"><td>{{r.supporting_store?.store_code}} {{r.supporting_store?.store_name}}</td><td>{{r.requested_count}}</td><td><div v-for="s in (data.supportStaff||[]).filter((s:any)=>s.support_request_id===r.id)">{{s.employee_code}} {{s.employee_name}}</div></td><td>{{r.notes}}</td><td><template v-if="permissions.requests"><button :disabled="tab.busy" @click="editRequest(r)">編輯需求</button><button :disabled="tab.busy" @click="removing=r">刪除需求</button></template><button v-if="permissions.supportStaff" :disabled="tab.busy" @click="openAssigned(r)">指派支援人員</button></td></tr></tbody></table></div>
<h3>預估活動人數</h3><form @submit.prevent="saveCount"><fieldset :disabled="!permissions.headcount||tab.busy||!!errors.headcount"><div class="fields"><label>額外支援人數<input type="number" min="0" step="1" v-model.number="counts.extra_support_count" required></label><label>督導人數<input type="number" min="0" step="1" v-model.number="counts.supervisor_count" required></label><label class="wide">備註<textarea v-model="counts.notes"/></label></div><p>本店 {{own.length}} ＋ 額外支援 {{counts.extra_support_count}} ＋ 督導 {{counts.supervisor_count}} ＝ {{own.length+Number(counts.extra_support_count)+Number(counts.supervisor_count)}} 人</p><button type="button" v-if="permissions.headcount&&changed('counts',counts)" @click="confirmDiscard='counts'">取消人數修改</button><button v-if="permissions.headcount" class="primary" :disabled="!changed('counts',counts)">儲存預估人數</button></fieldset></form></section>
<section v-show="active==='checklist'"><h3>前置工作完成情形（{{completed}}／{{data.checklist?.length||0}}）</h3><label class="check"><input type="checkbox" v-model="hideCompleted">隱藏已完成</label><div v-for="i in visibleChecks" :key="i.id" class="check-row"><h4>{{i.task_name}}</h4><p>安排人員：{{i.assigned_person||'未設定'}} · 期限：{{i.deadline||'未設定'}}</p><p>{{i.notes}}</p><fieldset :disabled="!permissions.completions||tab.busy||!!errors.completions"><label class="check"><input type="checkbox" v-model="checks[i.id].is_completed">已完成</label><label>門市負責人<input v-model="checks[i.id].store_assigned_person"></label><label>店長回報<textarea v-model="checks[i.id].manager_note"/></label><button v-if="permissions.completions" @click="saveCheck(i.id)">儲存此項回報</button></fieldset></div><p v-if="!visibleChecks.length">沒有符合條件的工作項目。</p></section></template>
<Modal v-if="requestForm" title="支援門市需求" :busy="tab.busy" @cancel="closeInner('request')"><form @submit.prevent="saveRequest"><fieldset :disabled="tab.busy"><label>支援門市<select aria-label="支援門市" v-model="requestForm.supporting_store_id" :disabled="requestForm.existing" required><option value="">請選擇</option><option v-for="s in stores.filter(s=>s.id!==store.id)" :value="s.id">{{s.store_code}} {{s.store_name}}</option></select></label><label>需求人數<input type="number" min="1" step="1" v-model.number="requestForm.requested_count" required></label><label>備註<textarea v-model="requestForm.notes"/></label></fieldset><p v-if="errors.action" role="alert">{{errors.action}}</p><div class="dialog-actions"><button type="button" :disabled="tab.busy" @click="closeInner('request')">取消</button><button class="primary" :disabled="tab.busy">儲存需求</button></div></form></Modal>
<Modal v-if="assigned" title="指派支援人員" :busy="tab.busy" @cancel="closeInner('assigned')"><p>{{assigned.supporting_store?.store_name}} → {{store.store_name}}，需求 {{assigned.requested_count}} 人</p><CampaignStaffSearch :disabled="tab.busy" @select="addAssigned"/><ul><li v-for="(r,i) in assignedRows">{{r.employee_code}} {{r.employee_name}} <button :disabled="tab.busy" @click="assignedRows.splice(i,1)">移除</button></li></ul><p v-if="errors.action" role="alert">{{errors.action}}</p><div class="dialog-actions"><button :disabled="tab.busy" @click="closeInner('assigned')">取消</button><button class="primary" :disabled="tab.busy" @click="saveAssigned">儲存指派</button></div></Modal>
<Modal v-if="confirmDiscard" title="放棄修改？" @cancel="confirmDiscard=''"><p>未儲存的內容將被放棄，已儲存的其他區塊不受影響。</p><div class="dialog-actions"><button @click="confirmDiscard=''">繼續編輯</button><button class="danger" @click="discardChanges">放棄修改</button></div></Modal>
<Modal v-if="reloadOwn" title="重新載入月度人員？" @cancel="reloadOwn=false"><p>會取代目前本店人員草稿，載入後仍須按「儲存本店人員」才會生效。</p><div class="dialog-actions"><button @click="reloadOwn=false">取消</button><button @click="fromMonthly">載入月度人員</button></div></Modal>
<Modal v-if="removing" title="刪除支援需求？" :busy="tab.busy" @cancel="removing=null"><p>此需求與其已指派人員將一併刪除。</p><p v-if="errors.action" role="alert">{{errors.action}}</p><div class="dialog-actions"><button :disabled="tab.busy" @click="removing=null">取消</button><button class="danger" :disabled="tab.busy" @click="deleteRequest">確認刪除</button></div></Modal>
</template>
<style scoped>.sections{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.sections [aria-pressed=true]{background:var(--primary);color:white}fieldset{border:0;padding:0;min-width:0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.wide{grid-column:1/-1}label{display:grid;gap:8px;margin:12px 0}input,select,textarea{width:100%}.check{display:flex;align-items:center;gap:8px}.check input{width:18px;min-height:18px}h3{font-size:17px;border-top:1px solid var(--line);padding-top:20px;margin-top:24px}td button{margin:3px}.check-row{border-bottom:1px solid var(--line);padding:16px 0}.check-row h4{font-size:15px}details{margin:16px 0}@media(max-width:650px){.fields{grid-template-columns:1fr}}</style>
